 "content": "from collections import deque


def transform(grid):
    """Fill every enclosed background region with color 7."""
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    outside = set()
    q = deque()

    # Flood-fill background reachable from the grid boundary.
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == bg and (r, c) not in outside:
                outside.add((r, c))
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == bg and (r, c) not in outside:
                outside.add((r, c))
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg
                    and (nr, nc) not in outside):
                outside.add((nr, nc))
                q.append((nr, nc))

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and (r, c) not in outside:
                out[r][c] = 7
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
